DO $$ DECLARE original text; modificada text; BEGIN SELECT pg_get_functiondef('public.tend_at_guard()'::regprocedure) INTO original; modificada:=replace(original,'IF auth.uid() IS DISTINCT FROM OLD.elaborado_version_por AND NOT public.tend_acceso(NEW.org_id,true,ARRAY[''admin'',''responsable_sanitario'']) AND su IS NULL THEN RAISE EXCEPTION ''Solo autor, admin, RS o suplente vigente anula borrador''; END IF;','IF NOT public.has_role(auth.uid(),''responsable_sanitario'') AND su IS NULL THEN RAISE EXCEPTION ''Solo RS o suplente vigente anula borrador''; END IF;'); IF modificada=original THEN RAISE EXCEPTION 'Guard de anulación no coincide; cambio no aplicado'; END IF; EXECUTE modificada; END $$;